290	function syncContactHead(progress: number): void {
291	  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
292	  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
293	  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
294	  if (!section || !head || !actions) return;
295	  const textItems = Array.from(
296	    head.querySelectorAll<HTMLElement>(".mask-target"),
297	  );
298	  const actionItems = Array.from(
299	    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
300	  );
301	  // Keep the contact panel visible through the footer zone and hide it only
302	  // when the scene is left or rewound before the reveal threshold.
303	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
304	
305	  if (mainSceneDomState.isContactActionsVisible !== shouldShow) {
306	    mainSceneDomState.isContactActionsVisible = shouldShow;
307	    mainSceneDomState.contactActionTimers = clearTimers(
308	      mainSceneDomState.contactActionTimers,
309	    );
310	    const queue = shouldShow ? actionItems : actionItems.slice().reverse();
311	    const delayStep = shouldShow
312	      ? CONTACT_HEAD_TRANSITION.revealStagger
313	      : CONTACT_HEAD_TRANSITION.hideStagger;
314	    queue.forEach((item, index) => {
315	      const timerId = window.setTimeout(
316	        () => {
317	          item.classList.add(INIT_DOM_CLASSES.blockBase);
318	          item.classList.remove(INIT_DOM_CLASSES.boxHidden);
319	          if (shouldShow) {
320	            item.classList.remove("is-block-reveal-down");
321	            BlockReveal.reveal(item);
322	            return;
323	          }
324	          item.classList.remove(INIT_DOM_CLASSES.blockUp);
325	          item.classList.add("is-block-reveal-down");
326	        },
327	        index * delayStep * 1000,
328	      );
329	      mainSceneDomState.contactActionTimers.push(timerId);
330	    });
331	  }
332	
333	  if (mainSceneDomState.isContactHeadVisible === shouldShow) return;
334	  mainSceneDomState.isContactHeadVisible = shouldShow;
335	  mainSceneDomState.contactHeadTimers = clearTimers(
336	    mainSceneDomState.contactHeadTimers,
337	  );
338	
339	  if (shouldShow) {
340	    section.dataset.active = "true";
341	    head.dataset.active = "true";
342	    actions.dataset.active = "true";
343	    TextReveal.setVisibleOff(textItems);
344	    textItems.forEach((item, index) => {
345	      const timerId = window.setTimeout(
346	        () => {
347	          TextReveal.setVisibleOn(item);
348	        },
349	        index * CONTACT_HEAD_TRANSITION.revealStagger * 1000,
350	      );
351	      mainSceneDomState.contactHeadTimers.push(timerId);
352	    });
353	    return;
354	  }
355	
356	  textItems
357	    .slice()
358	    .reverse()
359	    .forEach((item, index) => {
360	      const timerId = window.setTimeout(
361	        () => {
362	          TextReveal.setVisibleOff(item);
363	        },
364	        index * CONTACT_HEAD_TRANSITION.hideStagger * 1000,
365	      );
366	      mainSceneDomState.contactHeadTimers.push(timerId);
367	    });
368	
369	  const hideTimerId = window.setTimeout(
370	    () => {
371	      section.dataset.active = "false";
372	      head.dataset.active = "false";
373	      actions.dataset.active = "false";
374	    },
375	    (Math.max(textItems.length - 1, 0) *
376	      CONTACT_HEAD_TRANSITION.hideStagger +
377	      CONTACT_HEAD_TRANSITION.hideSettleDuration) *
378	      1000,
379	  );
380	  mainSceneDomState.contactHeadTimers.push(hideTimerId);
381	}
