383	function disposeContactHead(): void {
384	  mainSceneDomState.isContactHeadVisible = false;
385	  mainSceneDomState.contactHeadTimers = clearTimers(
386	    mainSceneDomState.contactHeadTimers,
387	  );
388	  mainSceneDomState.isContactActionsVisible = false;
389	  mainSceneDomState.contactActionTimers = clearTimers(
390	    mainSceneDomState.contactActionTimers,
391	  );
392	  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
393	  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
394	  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
395	  if (!section || !head || !actions) return;
396	  section.dataset.active = "false";
397	  head.dataset.active = "false";
398	  actions.dataset.active = "false";
399	  const textItems = Array.from(
400	    head.querySelectorAll<HTMLElement>(".mask-target"),
401	  );
402	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
403	  const actionItems = Array.from(
404	    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
405	  );
406	  actionItems.forEach((item) => {
407	    item.classList.add(INIT_DOM_CLASSES.blockBase);
408	    item.classList.remove(INIT_DOM_CLASSES.blockUp, "is-block-reveal-down");
409	    item.classList.add(INIT_DOM_CLASSES.boxHidden);
410	  });
411	}
