162	  private _attachPanelLights(group: THREE.Group): void {
163	    const specs = this._options.panelLights ?? [];
164	    if (!specs.length) return;
165	
166	    const exactById = new Map(specs.map((spec) => [spec.id, spec as LightSpec]));
167	    const partialSpecs = specs
168	      .map((spec) => {
169	        const raw = (spec as LightSpec & { match?: string | string[] }).match;
170	        const tokens = Array.isArray(raw)
171	          ? raw
172	          : typeof raw === "string"
173	            ? [raw]
174	            : [];
175	        const normalized = tokens
176	          .map((token) => token.trim().toLowerCase())
177	          .filter((token) => token.length > 0);
178	        return { spec: spec as LightSpec, tokens: normalized };
179	      })
180	      .filter((entry) => entry.tokens.length > 0);
181	
182	    group.traverse((obj) => {
183	      if (!(obj instanceof THREE.Mesh)) return;
184	      const mat = obj.material;
185	      const matName =
186	        (Array.isArray(mat) ? mat[0]?.name : (mat as THREE.Material)?.name) ??
187	        "";
188	      const objName = obj.name ?? "";
189	      const names = [objName, matName]
190	        .map((name) => name.trim())
191	        .filter((name) => name.length > 0);
192	      const namesLower = names.map((name) => name.toLowerCase());
193	      const exactKey = names.find((name) => exactById.has(name));
194	      const partial = partialSpecs.find((entry) =>
195	        entry.tokens.some((token) =>
196	          namesLower.some((name) => name.includes(token)),
197	        ),
198	      );
199	      const spec = exactKey ? exactById.get(exactKey)! : partial?.spec;
200	      if (!spec) return;
201	
202	      if (
203	        !Number.isFinite(spec.color as number) ||
204	        !Number.isFinite(spec.intensity as number)
205	      ) {
206	        return;
207	      }
208	
209	      const light = createPointLightFromSpec(
210	        spec,
211	        Number(spec.color),
212	        Number(spec.intensity),
213	      );
214	      const position = spec.position ?? {};
215	      light.position.set(position.x ?? 0, position.y ?? 0, position.z ?? 0);
216	      light.name = `ground:${spec.id}`;
217	      obj.add(light);
218	      this._panelLights.push(light);
219	    });
220	  }
