275	  private _applyGroundShader(group: THREE.Group): void {
276	    this._shaderMaterials = [];
277	    if (!this._isShaderEnabled()) return;
278	    if (!this._shaderNoiseTexture || !this._shaderNearestNoiseTexture || !this._mouseTexture) {
279	      return;
280	    }
281	    const replacedMaterials = new Set<THREE.Material>();
282	    group.traverse((child) => {
283	      if (!(child instanceof THREE.Mesh)) return;
284	      const currentMaterials = Array.isArray(child.material)
285	        ? child.material
286	        : [child.material];
287	      if (currentMaterials.some((m) => m?.userData?.__groundShaderApplied)) {
288	        return;
289	      }
290	      for (const material of currentMaterials) replacedMaterials.add(material);
291	      child.material = this._createShaderMaterialSet(child.material);
292	    });
293	    for (const material of replacedMaterials) material.dispose();
294	  }
