309	        uGroundTime: { value: this._elapsedTime },
310	        uGroundPage: { value: this._readShaderRuntimeValue("page") },
311	        uGroundScrollProgress: {
312	          value: this._readShaderRuntimeValue("scrollProgress"),
313	        },
314	        uGroundTransition: {
315	          value: this._readShaderRuntimeValue("transition"),
316	        },
317	        uGroundTransitionDirection: {
318	          value: this._readShaderRuntimeValue("transitionDirection"),
319	        },
320	        uGroundChapter: {
321	          value: this._readShaderRuntimeValue("chapter"),
322	        },
323	        uGroundTransitionColor: {
324	          value: this._transitionColor.clone(),
325	        },
326	        uGroundLightColor: {
327	          value: this._lightColor.clone(),
328	        },
329	        uGroundDarkColor: {
330	          value: this._darkColor.clone(),
331	        },
332	        tGroundNoise: { value: this._shaderNoiseTexture },
333	        tGroundNearestNoise: {
334	          value: this._shaderNearestNoiseTexture,
335	        },
336	        tGroundMouse: { value: this._mouseTexture },
337	      },
