350	  private _syncShaderUniforms(): void {
351	    if (this._shaderMaterials.length === 0) return;
352	    this._updateResolution();
353	    this._resolveShaderColors();
354	    const page = this._readShaderRuntimeValue("page");
355	    const scrollProgress = this._readShaderRuntimeValue("scrollProgress");
356	    const transition = this._readShaderRuntimeValue("transition");
357	    const transitionDirection = this._readShaderRuntimeValue(
358	      "transitionDirection",
359	    );
360	    const chapter = this._readShaderRuntimeValue("chapter");
361	    for (const material of this._shaderMaterials) {
362	      material.uniforms.uGroundResolution.value.copy(this._resolution);
363	      material.uniforms.uGroundTime.value = this._elapsedTime;
364	      material.uniforms.uGroundPage.value = page;
365	      material.uniforms.uGroundScrollProgress.value = scrollProgress;
366	      material.uniforms.uGroundTransition.value = transition;
367	      material.uniforms.uGroundTransitionDirection.value = transitionDirection;
368	      material.uniforms.uGroundChapter.value = chapter;
369	      material.uniforms.uGroundTransitionColor.value.copy(
370	        this._transitionColor,
371	      );
372	      material.uniforms.uGroundLightColor.value.copy(this._lightColor);
373	      material.uniforms.uGroundDarkColor.value.copy(this._darkColor);
