406	  private _updateResolution(): void {
407	    if (typeof window === "undefined") {
408	      this._resolution.set(
409	        GROUND_DEFAULT_RESOLUTION,
410	        GROUND_DEFAULT_RESOLUTION,
411	      );
412	      return;
413	    }
414	    const snapshot = ResponsiveRuntime.getDefault().getSnapshot();
415	    this._resolution.set(
416	      Math.max(GROUND_DEFAULT_RESOLUTION, snapshot.viewportWidth),
417	      Math.max(GROUND_DEFAULT_RESOLUTION, snapshot.viewportHeight),
418	    );
419	  }
