421	  private _updateMouseTexture(): void {
422	    const mouseTexture = this._mouseTexture;
423	    const mouseTextureData = this._mouseTextureData;
424	    if (!mouseTexture || !mouseTextureData) return;
425	    for (
426	      let index = 0;
427	      index < mouseTextureData.length;
428	      index += GROUND_MOUSE_TEXTURE_CHANNELS
429	    ) {
430	      mouseTextureData[index] *= GROUND_MOUSE_TEXTURE_FADE;
431	      mouseTextureData[index + 1] *= GROUND_MOUSE_TEXTURE_FADE;
432	      mouseTextureData[index + 2] *= GROUND_MOUSE_TEXTURE_FADE;
433	      mouseTextureData[index + 3] = 1;
434	    }
435	    if (!this._pointerActive) {
436	      mouseTexture.needsUpdate = true;
437	      return;
438	    }
439	
440	    const size = this._mouseTextureSize;
441	    const pointerX = this._pointerUv.x * (size - 1);
442	    const pointerY = this._pointerUv.y * (size - 1);
443	    const radius = Math.max(1, Math.round(size * GROUND_MOUSE_TEXTURE_RADIUS));
444	
445	    for (let y = -radius; y <= radius; y += 1) {
446	      const pixelY = Math.round(pointerY + y);
447	      if (pixelY < 0 || pixelY >= size) continue;
448	      for (let x = -radius; x <= radius; x += 1) {
449	        const pixelX = Math.round(pointerX + x);
450	        if (pixelX < 0 || pixelX >= size) continue;
451	        const distance = Math.sqrt(x * x + y * y) / radius;
452	        if (distance > 1) continue;
453	        const strength = Math.pow(1 - distance, GROUND_MOUSE_TEXTURE_FALLOFF);
454	        const pixelIndex =
455	          (pixelY * size + pixelX) * GROUND_MOUSE_TEXTURE_CHANNELS;
456	        mouseTextureData[pixelIndex] = Math.max(
457	          mouseTextureData[pixelIndex],
458	          strength,
459	        );
460	        mouseTextureData[pixelIndex + 1] = Math.max(
461	          mouseTextureData[pixelIndex + 1],
462	          strength * 0.6,
463	        );
464	        mouseTextureData[pixelIndex + 2] = Math.max(
465	          mouseTextureData[pixelIndex + 2],
466	          strength * 0.85,
467	        );
468	      }
469	    }
470	
471	    mouseTexture.needsUpdate = true;
472	  }
