474	  private _installPointerListeners(): void {
475	    if (this._pointerListenersAttached || typeof window === "undefined") return;
476	    window.addEventListener("pointermove", this._onPointerMove, { passive: true });
477	    window.addEventListener("pointerleave", this._onPointerLeave);
478	    this._pointerListenersAttached = true;
479	  }
480	
481	  private _removePointerListeners(): void {
482	    if (!this._pointerListenersAttached || typeof window === "undefined") return;
483	    window.removeEventListener("pointermove", this._onPointerMove);
484	    window.removeEventListener("pointerleave", this._onPointerLeave);
485	    this._pointerListenersAttached = false;
486	  }
