488	  private _disposeShaderResources(): void {
489	    this._shaderMaterials = [];
490	    this._shaderNoiseTexture?.dispose();
491	    this._shaderNearestNoiseTexture?.dispose();
492	    this._mouseTexture?.dispose();
493	    this._shaderNoiseTexture = null;
494	    this._shaderNearestNoiseTexture = null;
495	    this._mouseTexture = null;
496	    this._mouseTextureData = null;
497	    this._mouseTextureSize = GROUND_SHADER_DEFAULTS.mouseTextureSize;
498	  }
499	
500	  private _isShaderEnabled(): boolean {
501	    return this._options.shader?.enabled ?? GROUND_SHADER_DEFAULTS.enabled;
502	  }
503	
504	  private _disposeGroup(group: THREE.Group | null): void {
505	    if (!group) return;
506	    group.traverse((child) => {
507	      if (!(child as THREE.Mesh).isMesh) return;
508	      const mesh = child as THREE.Mesh;
509	      mesh.geometry?.dispose();
510	      const materials = Array.isArray(mesh.material)
511	        ? mesh.material
512	        : [mesh.material];
513	      for (const material of materials) {
514	        material?.dispose?.();
515	      }
516	    });
517	  }
518	}
